const SERVER_KEY = [
  { id: 's1', questionText: "The mission of Three Points Hospitality emphasizes enriching the dining experience of whom?", correctAnswer: "The mission of Three Points Hospitality is to enrich the dining experience of our guests, our employees, and owners with superior quality food and beverages, excellent guest service, sales growth, cost controls, and treating employees with respect.", points: 2, gradingType: 'conceptual', requiredConcepts: ['guests', 'employees', 'owners'], minimumConcepts: 2 },
  { id: 's2', questionText: "What is worn as part of your dining room dress code? List Top & Bottom Requirements.", correctAnswer: "OAK/Cantina/Company Shirt or Polo. Dark jeans without holes or designs, paired with belt. Black non-slip shoes. Clothing must be neat and clean, long hair must be tied back, hands and fingernails must be well-groomed. Avoid wearing scented lotions or perfumes.", points: 3, gradingType: 'conceptual', requiredConcepts: ['company shirt/polo', 'dark jeans without holes', 'black non-slip shoes', 'neat and clean appearance'], minimumConcepts: 3 },
  { id: 's3', questionText: "What is the key focus (First and most important focus) of the 'Five Basics of Service Excellence' at Three Points Hospitality?", correctAnswer: 'The first and most important focus is "Look at me".', points: 2, gradingType: 'factual' },
  { id: 's4', questionText: "When should a server at all Three Points Hospitality venues arrive for their shift?", correctAnswer: "A server should arrive promptly to their shift", points: 1, gradingType: 'factual' },
  { id: 's5', questionText: "List a suggested practice for enhancing the guest experience through suggestive selling:", correctAnswer: "A suggested practice is to use upselling techniques by suggesting additional items, promotions, or upgrades to increase check averages. Other practices include mentioning specials, and learning basic food and drink pairing suggestions", points: 2, gradingType: 'conceptual', requiredConcepts: ['suggest additional items or upgrades', 'mention specials or promotions', 'increase check average'], minimumConcepts: 1 },
  { id: 's6', questionText: 'What should a server do if they make a small mistake during service?', correctAnswer: "The server should stay relaxed, alert, and efficient and always maintain control of the situation. If it's a mistake on the bill (over ring), they must immediately notify the kitchen or bar not to prepare the item, split off the incorrect items, and inform the manager.", points: 2, gradingType: 'conceptual', requiredConcepts: ['stay calm/relaxed', 'maintain control', 'notify kitchen/bar immediately', 'inform manager'], minimumConcepts: 2 },
  { id: 's7', questionText: "Which of the following behaviors is a turn-off for guests at Three Points Hospitality?", correctAnswer: "Behaviors to avoid (turn-offs) include: approaching guests with dirty plates , forming \"discussion groups\" of three or four idle servers in guest areas , ignoring guests , and having an unpositive attitude.", points: 2, gradingType: 'conceptual', requiredConcepts: ['dirty plates', 'idle servers in groups', 'ignoring guests', 'negative attitude'], minimumConcepts: 2 },
  { id: 's8', questionText: "What is the most important quality for a server to maintain during guest interactions according to the guidelines?", correctAnswer: "An energetic, friendly, and caring attitude is essential at all times. The server should also be professional and confident.", points: 2, gradingType: 'conceptual', requiredConcepts: ['energetic/friendly attitude', 'caring demeanor', 'professional and confident'], minimumConcepts: 2 },
  { id: 's9', questionText: "What is the primary responsibility of a server during the process of pre-bussing a table?", correctAnswer: "The primary responsibility is clearing used or empty dishes, glasses, and utensils from the table before the guests have finished their meal. This helps keep the table tidy and ensures guests have ample space for the next course.", points: 2, gradingType: 'conceptual', requiredConcepts: ['clear used/empty items', 'before guests finish meal', 'keep table tidy', 'make space for next course'], minimumConcepts: 2 }
];

const HOST_KEY = [
  { id: 'h1', questionText: "What information do you need to take when making a reservation?", correctAnswer: "First & last name, Telephone number, E-mail address, and Notes (such as birthday, highchair, wheelchair, booth, outside seating).", points: 3, gradingType: 'factual' },
  { id: 'h2', questionText: "What extra information do you need from a guest to make a reservation during graduation weekends?", correctAnswer: "A credit card is required to secure the reservation, which must be entered into the Resy app.", points: 2, gradingType: 'factual' },
  { id: 'h3', questionText: "Cancellation within three days or no-shows incur a $___ charge per guest.", correctAnswer: "$10", points: 1, gradingType: 'factual' },
  { id: 'h4', questionText: "For reservation requests, enter details into the Resy app. For parties larger than ___ guests, direct them to book as an event.", correctAnswer: "20", points: 1, gradingType: 'factual' },
  { id: 'h5', questionText: "Tables Occupied for 30-60 Minutes What would be an appropriate quote wait time?", correctAnswer: "15-20 minute wait time.", points: 1, gradingType: 'factual' },
  { id: 'h6', questionText: "If a guest asks to book the private event or catering, please explain what you would say to them on the telephone or in person:", correctAnswer: "Advise the guest to complete our contact form on the website or email us directly, as reservations over 20 guests, private events, or catering should be directed to management.", points: 3, gradingType: 'conceptual', requiredConcepts: ['complete contact form or email', 'over 20 guests = event', 'directed to management'], minimumConcepts: 2 },
  { id: 'h7', questionText: "When do we post graduation menus on our website?", correctAnswer: "A month before the graduation weekend.", points: 1, gradingType: 'factual' },
  { id: 'h8', questionText: "Explain in 2 sentences: What pre-bussing & post-dining clean-up is.", correctAnswer: "Pre-bussing involves removing unnecessary items from the table while guests are still dining to maintain a clean appearance and improve the experience. Post-dining clean-up is promptly busing, cleaning the tabletop and chairs, and resetting the area with clean linens and place settings once guests have left.", points: 3, gradingType: 'conceptual', requiredConcepts: ['pre-bussing = remove items while dining', 'maintain clean appearance', 'post-dining = clean and reset', 'after guests leave'], minimumConcepts: 3 },
  { id: 'h9', questionText: "A guest approaches you and says, \"I don't see why I need a reservation.\" What would be the appropriate way to respond?", correctAnswer: "\"Reservations help us manage the flow of guests and ensure that everyone receives timely service. While we do accept walk-ins, having a reservation guarantees your table at your preferred time.\"", points: 3, gradingType: 'conceptual', requiredConcepts: ['manage flow of guests', 'ensure timely service', 'accept walk-ins', 'reservation guarantees table at preferred time'], minimumConcepts: 2 },
  { id: 'h10', questionText: "Servers are allowed to tell you when they are no longer taking tables:", correctAnswer: "FALSE", points: 1, gradingType: 'factual' },
  { id: 'h11', questionText: "A guest asks, \"Can you accommodate additional guests in our party?\" What would be the best way to respond?", correctAnswer: "Check availability in Resy first. If space permits, update the party size. If fully booked, inform them politely that we cannot guarantee seats for the extra guests but will try our best upon arrival.", points: 2, gradingType: 'conceptual', requiredConcepts: ['check Resy availability', 'update party size if possible', 'politely inform if cannot guarantee', 'try our best'], minimumConcepts: 2 },
  { id: 'h12', questionText: "A guest arrives at the restaurant without a reservation during a busy evening. What is the most appropriate way for the host to handle this situation?", correctAnswer: "Greet them warmly, inform them of the current wait time, add them to the waitlist if they agree, and suggest they can wait in the bar area or text them when the table is ready.", points: 2, gradingType: 'conceptual', requiredConcepts: ['greet warmly', 'inform wait time', 'add to waitlist', 'suggest bar area or text when ready'], minimumConcepts: 3 },
  { id: 'h13', questionText: "If a guest becomes upset because their table isn't ready on time, how should you handle the situation?", correctAnswer: "Remain calm, apologize for the delay, explain the situation honestly (e.g. \"The previous guests are just finishing up\"), and offer a gesture of hospitality such as a complimentary drink or appetizer if within policy, or update them frequently.", points: 2, gradingType: 'conceptual', requiredConcepts: ['remain calm', 'apologize for delay', 'explain situation honestly', 'offer gesture of hospitality or updates'], minimumConcepts: 3 },
  { id: 'h14', questionText: "What is the best way to handle a situation where two different parties claim to have the same reservation?", correctAnswer: "Verify the reservation details (phone number, confirmation email). Identify which party holds the actual reservation. Apologize to the other party and attempt to accommodate them immediately as a priority walk-in or offer bar seating.", points: 2, gradingType: 'conceptual', requiredConcepts: ['verify reservation details', 'identify actual reservation holder', 'apologize to other party', 'accommodate as priority walk-in'], minimumConcepts: 3 },
  { id: 'h15', questionText: "A guest calls and requests to make a reservation, explain your process in detail with steps.", correctAnswer: "When a guest calls, I start with a warm greeting and immediately ask for their preferred date, time, and party size to check our availability. Once a slot is confirmed, I collect the guest's name and phone number, while also inquiring about any special occasions or dietary restrictions to personalize their experience. Finally, I repeat all the details back to the guest to ensure accuracy before thanking them and concluding the call.", points: 4, gradingType: 'conceptual', requiredConcepts: ['warm greeting', 'ask date/time/party size', 'check availability', 'collect name and phone', 'inquire about special occasions', 'repeat details back', 'thank them'], minimumConcepts: 4 }
];

